## Code Example
```javascript
function shouldSample(tenantId, rate){
  const h = 0|hashCode(tenantId);
  return Math.abs(h) % 100 < rate;
}
function hashCode(s){
  let h=0;
  for(let i=0;i<s.length;i++) h=(h*31+s.charCodeAt(i))|0;
  return h;
}
```

